selector .dt-js .elementskit-post-body p{order:3;margin:8px 0 0;color:#636363 !important;font-weight:500;}
selector .entry-title{order:2;margin:0;}
selector .entry-title a{color:#161616 !important;}
selector .entry-title a::after{content:"";position:absolute;inset:0;z-index:1;}
