selector .btn-wraper{position:absolute;right:0;top:50%;transform:translateY(-50%);margin:0;}
selector .btn-wraper a{position:relative;display:block;width:48px;height:48px;padding:0 !important;font-size:0 !important;color:#073C64 !important;border:1.5px solid #073C64;border-radius:50%;background:transparent !important;transition:background-color .2s,color .2s;}
selector .btn-wraper a::before{content:"";position:absolute;left:14px;top:50%;width:19px;height:2px;margin-top:-1px;background:currentColor;}
selector .btn-wraper a::after{content:"";position:absolute;right:14px;top:50%;width:9px;height:9px;margin-top:-5px;border-top:2px solid currentColor;border-right:2px solid currentColor;transform:rotate(45deg);}
selector .elementskit-post-image-card:hover .btn-wraper a{background:#073C64 !important;color:#FFFFFF !important;}
selector .dt-tgl{flex:none;width:92px;text-align:left;border-right:1px solid #E3E3E3;padding-right:20px;}
selector .dt-hari{display:block;font-family:"Plus Jakarta Sans",sans-serif;font-size:44px;font-weight:400;letter-spacing:-0.03em;line-height:1;color:#073C64;}
selector .dt-bln{display:block;margin-top:6px;font-size:14px;font-weight:600;color:#636363;line-height:1.2;}
